// src/App.js — khai báo MỌI route của CodeLearn ở một chỗ (nhìn là thấy cả sơ đồ trang)
import { Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import CoursesPage from './pages/CoursesPage';
import NotFoundPage from './pages/NotFoundPage';
import ProtectedRoute from './components/ProtectedRoute';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import AdminLayout from './pages/admin/AdminLayout';

export default function App() {
  return (
    <Routes>
      {/* Layout chung: navbar + <Outlet /> + footer cho mọi trang */}
      <Route element={<Layout />}>
        {/* ── Khách (guest) xem được ── */}
        <Route path="/" element={<HomePage />} />
        <Route path="/courses" element={<CoursesPage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />

        {/* ── Phải đăng nhập (học viên) ── */}
        <Route element={<ProtectedRoute />}>
        </Route>

        {/* ── Chỉ ADMIN — route lồng: AdminLayout có sidebar + <Outlet /> ── */}
        <Route path="/admin" element={<ProtectedRoute role="admin"><AdminLayout /></ProtectedRoute>}>
        </Route>

        {/* Mọi đường dẫn không khớp ⇒ 404 (luôn để CUỐI) */}
        <Route path="*" element={<NotFoundPage />} />
      </Route>
    </Routes>
  );
}

// src/api/courseApi.js — categories / courses / chapters / lessons (mọi hàm trả response.data)
import axiosClient from './axiosClient';

const courseApi = {
  getCategories: () => axiosClient.get('/categories').then((res) => res.data),
  // học viên/khách chỉ thấy khoá đã xuất bản (published=true) — lọc ở MÁY CHỦ
  getPublishedCourses: () => axiosClient.get('/courses', { params: { published: true } }).then((res) => res.data),
};

export default courseApi;

// src/features/courses/coursesSlice.js — danh mục khoá học (catalog)
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import courseApi from '../../api/courseApi';

// Danh sách công khai + danh mục: tải SONG SONG (Promise.all), một trạng thái tải chung
export const fetchCatalog = createAsyncThunk('courses/fetchCatalog', async () => {
  const [courses, categories] = await Promise.all([courseApi.getPublishedCourses(), courseApi.getCategories()]);
  return { courses, categories };
});

const initialState = {
  items: [],          // khoá đã xuất bản (trang /courses)
  categories: [],
  status: 'idle',     // idle | loading | succeeded | failed
  error: null,
};

const coursesSlice = createSlice({
  name: 'courses',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchCatalog.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchCatalog.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload.courses;
        state.categories = action.payload.categories;
      })
      .addCase(fetchCatalog.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      ;
  },
});

export default coursesSlice.reducer;

